import {Button} from '../../core/index.js';
import {THREE,FACE} from './geometry.js';
import {weightedInputHit} from '../../modeling/weighted-input.js';
// Own K130 rear U-tongue: root raw Y=-6.6; outer/inner native walls both move.
const polygon=[[11.099,-6.59],[16.22,-6.59],[16.22,-8.8],[13.08,-12.85],[12,-13.38],[11.099,-12.38]];
function inside(x,y){let result=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const[a,b]=polygon[i],[c,d]=polygon[j];if((b>y)!==(d>y)&&x<(c-a)*(y-b)/(d-b)+a)result=!result;}return result;}
export class NativeReset extends Button{
 constructor(shell){const target=new THREE.Mesh(new THREE.PlaneGeometry(2.8,2.8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));target.name='K130 reset input-only native tongue target';super({id:'reset',label:'RST · rear native tongue',mesh:target,travel:.16,position:[-13,-9.7,-11.72],quaternion:FACE.back,longPressMs:0,meta:{role:'visual-control',actuation:'native-flexure',surfaceFace:'back',surfaceCenter:[-13,-9.7,-11.72],scope:'Own U-tongue inferred visual flexure/input only;no reboot'}});this.shell=shell;this.rest=shell.geometry.attributes.position.array.slice();this.norm=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.rest.length/3);this.depth=0;for(let i=0;i<this.weights.length;i++){const[x,y,z]=this.rest.subarray(i*3,i*3+3);if(z>=9.88&&z<=11.71&&inside(x,y))this.weights[i]=THREE.MathUtils.clamp((-y-6.6)/6.78,0,1);}this.meta.movingNativeVertices=this.weights.filter(w=>w>0).length;this.hit(shell,intersection=>weightedInputHit(this,shell,intersection));}
 update(dt){const changed=super.update(dt),d=this.getActuationState().depthMm;if(d===this.depth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(let i=0;i<this.weights.length;i++){const w=this.weights[i];if(!w)continue;const k=i*3;let nx=this.norm[k],ny=this.norm[k+1]-d/6.78*this.norm[k+2],nz=this.norm[k+2],length=Math.hypot(nx,ny,nz);p.setXYZ(i,this.rest[k],this.rest[k+1],this.rest[k+2]-d*w);if(d)n.setXYZ(i,nx/length,ny/length,nz/length);else n.setXYZ(i,this.norm[k],this.norm[k+1],this.norm[k+2]);}p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();this.depth=d;return true;}
 dispose(){super.dispose();this.shell=null;this.rest=null;this.norm=null;this.weights=null;}
}
